public int FindMin(int[] nums)
{
    int min = nums[0];
    foreach (int n in nums)
        if (n < min) min = n;
    return min;
}

public int FindMin(int[] nums)
{
    int left = 0, right = nums.Length - 1;
    while (left < right)
    {
        int mid = left + (right - left) / 2;
        if (nums[mid] > nums[right])
            left = mid + 1;
        else
            right = mid;
    }
    return nums[left];
}
